// `bun run media:capture` (see client/scripts/capture-landing-media.mjs).
const STEPS = [
  {
    id: "log",
    eyebrow: "Log",
    title: "Log a set in seconds.",
    body: "Pick an exercise and your recent sets are right there. Save weight and reps, then repeat the last set with one tap.",
    points: [
      "Recent sets beside every exercise",
      "One tap to repeat the last set",
    ],
    caption: "Adding Bench Press to today's workout and logging three sets.",
  },
  {
    id: "repeat",
    eyebrow: "Repeat",
    title: "Start from what already worked.",
    body: "Open any past session and repeat it. Exercises and sets come back as today's draft, with your last note on top.",
    points: ["Copies exercises and sets", "Your last workout note resurfaces"],
    caption:
      "Opening Sunday's upper-body session and repeating it as a new draft.",
  },
  {
    id: "review",
    eyebrow: "Review",
    title: "See where training is going.",
    body: "Weekly pace, an activity map, and volume trends live together, so progress is visible without digging through old sessions.",
    points: [
      "Activity across the last few months",
      "Volume by week, month, or year",
    ],
    caption:
      "Scrolling analytics: workout pace, the activity map, and daily volume.",
  },
] as const;

type Step = (typeof STEPS)[number];

function StepClip({
  step,
  theme,
  active,
  playing,
  reducedMotion,
  className,
}: {
  step: Step;
  theme: "light" | "dark";
  active: boolean;
  playing: boolean;
  reducedMotion: boolean;
  className?: string;
}) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const base = `/media/how-it-works/${step.id}-${theme}`;

  // Rewind when the step stops being current, so it starts fresh next time
  // while a pause/resume on the current step continues where it left off.
  useEffect(() => {
    const video = videoRef.current;
    if (video && !active) video.currentTime = 0;
  }, [active]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    video.playbackRate = 0.65;
    if (playing && !reducedMotion) {
      video.play().catch(() => {
        // Autoplay can be refused (e.g. data saver); the poster stays visible.
      });
    } else if (!video.paused) {
      video.pause();
    }
  }, [playing, reducedMotion, base]);

  return (
    <video
      ref={videoRef}
      key={base}
      className={className}
      poster={`${base}.webp`}
      muted
      loop
      playsInline
      preload="none"
      aria-hidden="true"
    >
      <source
        src={`${base}.mp4`}
        type="video/mp4"
      />
    </video>
  );
}

// Looping clips run longer than five seconds, so visitors need a way to stop
// them (WCAG 2.2.2). One shared state drives every phone's toggle.
function PlaybackToggle({
  paused,
  onToggle,
}: {
  paused: boolean;
  onToggle: () => void;
}) {
  const Icon = paused ? Play : Pause;
  return (
    <button
      type="button"
      onClick={onToggle}
      aria-label={paused ? "Play demo videos" : "Pause demo videos"}
      className="absolute bottom-3 right-3 z-10 grid h-9 w-9 place-items-center rounded-full border border-border bg-background/85 text-foreground shadow-md backdrop-blur hover:bg-background focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
    >
      <Icon className="h-4 w-4" />
    </button>
  );
}

